&lt;h1 id=&#34;七-最小生成树&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#七-最小生成树&#34;&gt;#&lt;/a&gt; 七、最小生成树&lt;/h1&gt;
&lt;img data-src=&#34;\images\article_images\image-20251122091037575.png&#34; alt=&#34;image-20251122091037575&#34; style=&#34;zoom:50%;&#34; /&gt;
