 4.1 &lt;a href=&#34;#1.%E6%A8%A1%E6%9D%BF%E5%AE%9A%E4%B9%89%E7%9A%84%E9%93%BE%E8%A1%A8%E7%BB%93%E7%82%B9%E7%B1%BB&#34;&gt;模板定义的链表结点类&lt;/a&gt;&lt;br /&gt;
 4.2 &lt;a href=&#34;#2.%E6%A8%A1%E6%9D%BF%E5%AE%9A%E4%B9%89%E7%9A%84%E5%8F%8C%E5%90%91%E5%BE%AA%E7%8E%AF%E9%93%BE%E8%A1%A8%E7%B1%BB&#34;&gt;模板定义的双向循环链表类&lt;/a&gt;&lt;br /&gt;
 4.3 &lt;a href=&#34;#3.%E6%90%9C%E7%B4%A2%E7%AE%97%E6%B3%95&#34;&gt;搜索算法&lt;/a&gt;&lt;br /&gt;
 4.4 &lt;a href=&#34;#4.%E6%8F%92%E5%85%A5%E7%AE%97%E6%B3%95&#34;&gt;插入算法&lt;/a&gt;&lt;br /&gt;
 4.5 &lt;a href=&#34;#5.%E5%88%A0%E9%99%A4%E7%AE%97%E6%B3%95&#34;&gt;删除算法&lt;/a&gt;&lt;/p&gt;
